create or replace function scenario_teacher_daily_count_scope_v1(p_scenario uuid,p_teacher uuid,p_day smallint,p_assignment uuid) returns integer language sql stable security definer set search_path=public as $$select count(*)::int from schedule_scenario_rows r where r.scenario_id=p_scenario and r.teacher_id=p_teacher and r.weekday=p_day and schedule_assignment_scopes_overlap_v1(r.teacher_assignment_id,p_assignment)$$;
create or replace function scenario_teacher_working_days_scope_v1(p_scenario uuid,p_teacher uuid,p_candidate_day smallint,p_assignment uuid) returns integer language sql stable security definer set search_path=public as $$select count(distinct d)::int from(select weekday d from schedule_scenario_rows r where r.scenario_id=p_scenario and r.teacher_id=p_teacher and schedule_assignment_scopes_overlap_v1(r.teacher_assignment_id,p_assignment) union all select p_candidate_day where p_candidate_day is not null)q$$;
create or replace function scenario_teacher_consecutive_count_block_scope_v1(p_scenario uuid,p_teacher uuid,p_day smallint,p_start smallint,p_block smallint,p_assignment uuid) returns integer language sql stable security definer set search_path=public as $$with periods as(select distinct period::int p from schedule_scenario_rows r where r.scenario_id=p_scenario and r.teacher_id=p_teacher and r.weekday=p_day and schedule_assignment_scopes_overlap_v1(r.teacher_assignment_id,p_assignment) union select generate_series(p_start::int,(p_start+p_block-1)::int)),g as(select p,p-row_number()over(order by p)::int k from periods),runs as(select count(*)::int n from g group by k) select coalesce(max(n),0) from runs$$;
create or replace function schedule_relation_slot_allowed_v1(p_scenario_id uuid,p_requirement_id uuid,p_weekday smallint,p_period smallint,p_block smallint) returns boolean language plpgsql stable security definer set search_path=public as $$declare r record;o uuid;od smallint;os smallint;k int;begin for k in 0..p_block-1 loop if not schedule_requirement_slot_allowed_v1(p_requirement_id,(p_period+k)::smallint) then return false;end if;end loop;for r in select * from schedule_relation_rules where institution_code=current_tenant_code() and active and hard and(left_requirement_id=p_requirement_id or right_requirement_id=p_requirement_id) loop if r.rule_type='no_lunch_split' then if p_period<=r.lunch_after_period and p_period+p_block-1>r.lunch_after_period then return false;end if;continue;end if;o:=case when r.left_requirement_id=p_requirement_id then r.right_requirement_id else r.left_requirement_id end;if not exists(select 1 from schedule_scenario_rows where scenario_id=p_scenario_id and requirement_id=o) then continue;end if;if r.rule_type='different_day' and exists(select 1 from schedule_scenario_rows where scenario_id=p_scenario_id and requirement_id=o and weekday=p_weekday) then return false;end if;if r.rule_type='same_day' and not exists(select 1 from schedule_scenario_rows where scenario_id=p_scenario_id and requirement_id=o and weekday=p_weekday) then return false;end if;if r.rule_type='different_slot' and exists(select 1 from schedule_scenario_rows where scenario_id=p_scenario_id and requirement_id=o and weekday=p_weekday and period between p_period and p_period+p_block-1) then return false;end if;if r.rule_type='not_adjacent' and exists(select 1 from schedule_scenario_rows where scenario_id=p_scenario_id and requirement_id=o and weekday=p_weekday and period in(p_period-1,p_period+p_block)) then return false;end if;if r.rule_type='same_slot' then select weekday,min(period)::smallint into od,os from schedule_scenario_rows where scenario_id=p_scenario_id and requirement_id=o group by weekday order by weekday limit 1;if od<>p_weekday or os<>p_period then return false;end if;end if;end loop;return true;end$$;
do $$declare d text;begin select pg_get_functiondef(p.oid) into d from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='generate_schedule_scenarios';d:=replace(d,'public.scenario_teacher_daily_count(v_scenario,v_member.teacher_id,d)','public.scenario_teacher_daily_count_scope_v1(v_scenario,v_member.teacher_id,d,v_member.teacher_assignment_id)');d:=replace(d,'public.scenario_teacher_daily_count(v_scenario,v_item.teacher_id,d)','public.scenario_teacher_daily_count_scope_v1(v_scenario,v_item.teacher_id,d,v_item.assignment_id)');d:=replace(d,'public.scenario_teacher_working_days(v_scenario,v_member.teacher_id,d)','public.scenario_teacher_working_days_scope_v1(v_scenario,v_member.teacher_id,d,v_member.teacher_assignment_id)');d:=replace(d,'public.scenario_teacher_working_days(v_scenario,v_item.teacher_id,d)','public.scenario_teacher_working_days_scope_v1(v_scenario,v_item.teacher_id,d,v_item.assignment_id)');d:=replace(d,'public.scenario_teacher_consecutive_count_block_v2(v_scenario,v_member.teacher_id,d,p,v_member.block_hours)','public.scenario_teacher_consecutive_count_block_scope_v1(v_scenario,v_member.teacher_id,d,p,v_member.block_hours,v_member.teacher_assignment_id)');d:=replace(d,'public.scenario_teacher_consecutive_count_block_v2(v_scenario,v_item.teacher_id,d,p,v_block)','public.scenario_teacher_consecutive_count_block_scope_v1(v_scenario,v_item.teacher_id,d,p,v_block,v_item.assignment_id)');d:=replace(d,'x.teacher_id=v_member.teacher_id and x.weekday=d and x.period=p+k','x.teacher_id=v_member.teacher_id and x.weekday=d and x.period=p+k and public.schedule_assignment_scopes_overlap_v1(x.teacher_assignment_id,v_member.teacher_assignment_id)');d:=replace(d,'x.teacher_id=v_item.teacher_id and x.weekday=d and x.period=p+k','x.teacher_id=v_item.teacher_id and x.weekday=d and x.period=p+k and public.schedule_assignment_scopes_overlap_v1(x.teacher_assignment_id,v_item.assignment_id)');d:=replace(d,'x.class_id=v_member.class_id and x.weekday=d and x.period=p+k','x.class_id=v_member.class_id and x.weekday=d and x.period=p+k and public.schedule_assignment_scopes_overlap_v1(x.teacher_assignment_id,v_member.teacher_assignment_id)');d:=replace(d,'x.class_id=v_item.class_id and x.weekday=d and x.period=p+k','x.class_id=v_item.class_id and x.weekday=d and x.period=p+k and public.schedule_assignment_scopes_overlap_v1(x.teacher_assignment_id,v_item.assignment_id)');d:=replace(d,'x.teacher_id=v_item.teacher_id and x.weekday=d and x.period in (p-1,p+v_block)','x.teacher_id=v_item.teacher_id and x.weekday=d and x.period in (p-1,p+v_block) and public.schedule_assignment_scopes_overlap_v1(x.teacher_assignment_id,v_item.assignment_id)');execute d;
select pg_get_functiondef(p.oid) into d from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='get_schedule_scenario_student_conflict_summary_v1';d:=replace(d,'on a.weekday=b.weekday and a.period=b.period and a.teacher_assignment_id<b.teacher_assignment_id','on a.weekday=b.weekday and a.period=b.period and a.teacher_assignment_id<b.teacher_assignment_id and public.schedule_assignment_scopes_overlap_v1(a.teacher_assignment_id,b.teacher_assignment_id)');execute d;
select pg_get_functiondef(p.oid) into d from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='get_schedule_student_conflict_report_v2';d:=replace(d,'tb.weekday=ta.weekday and tb.period=ta.period','tb.weekday=ta.weekday and tb.period=ta.period and public.schedule_assignment_scopes_overlap_v1(a.teacher_assignment_id,b.teacher_assignment_id)');execute d;
select pg_get_functiondef(p.oid) into d from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='get_schedule_scenario_room_candidates_v2';d:=replace(d,'x.scenario_id=p_scenario_id and x.teacher_id=r.teacher_id and x.weekday=r.weekday and x.period in(r.period-1,r.period+1)','x.scenario_id=p_scenario_id and x.teacher_id=r.teacher_id and x.weekday=r.weekday and x.period in(r.period-1,r.period+1) and public.schedule_assignment_scopes_overlap_v1(x.teacher_assignment_id,r.teacher_assignment_id)');d:=replace(d,'x.scenario_id=p_scenario_id and x.weekday=r.weekday and x.period=r.period and x.classroom_id=c.id and x.id<>r.id','x.scenario_id=p_scenario_id and x.weekday=r.weekday and x.period=r.period and x.classroom_id=c.id and x.id<>r.id and public.schedule_assignment_scopes_overlap_v1(x.teacher_assignment_id,r.teacher_assignment_id)');d:=replace(d,'x.scenario_id=p_scenario_id and x.weekday=r.weekday and x.period=r.period and cx.room_pool_id=c.room_pool_id and x.id<>r.id','x.scenario_id=p_scenario_id and x.weekday=r.weekday and x.period=r.period and cx.room_pool_id=c.room_pool_id and x.id<>r.id and public.schedule_assignment_scopes_overlap_v1(x.teacher_assignment_id,r.teacher_assignment_id)');d:=replace(d,'x.scenario_id=p_scenario_id and x.teacher_id=r.teacher_id and x.weekday=r.weekday and x.period in(r.period-1,r.period+1) and x.id<>r.id','x.scenario_id=p_scenario_id and x.teacher_id=r.teacher_id and x.weekday=r.weekday and x.period in(r.period-1,r.period+1) and x.id<>r.id and public.schedule_assignment_scopes_overlap_v1(x.teacher_assignment_id,r.teacher_assignment_id)');execute d;end$$;